import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function JoinRoom() {
  const [code, setCode] = useState("");
  const [status, setStatus] = useState("");
  const navigate = useNavigate();

  const createRoom = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/create-room", {
        method: "POST"
      });
      const data = await res.json();
      setCode(data.room);
      setStatus(`Room created: ${data.room} — click Join Room or copy code.`);
    } catch (err) {
      setStatus("Failed to create room — check backend.");
    }
  };

  const joinRoom = async () => {
    if (!code.trim()) {
      setStatus("Enter a room code.");
      return;
    }

    try {
      const res = await fetch(`http://127.0.0.1:8000/validate-room/${code}`);
      const data = await res.json();

      if (data.valid) {
        navigate(`/lobby?room=${code}`);
      } else {
        setStatus("Invalid room code.");
      }
    } catch (err) {
      setStatus("Server error validating room.");
    }
  };

  return (
    <div style={{
      fontFamily: "Inter, Arial",
      padding: "30px",
      background: "#0f0f10",
      color: "#fff",
      minHeight: "100vh"
    }}>
      <h1>Room Access</h1>

      <div style={{ margin: "12px 0" }}>
        <button
          onClick={createRoom}
          style={{
            background: "#1976d2",
            color: "#fff",
            border: "none",
            padding: "10px 14px",
            borderRadius: "6px",
            cursor: "pointer"
          }}
        >
          Create New Room
        </button>
        <span style={{ marginLeft: "10px" }}>or</span>
      </div>

      <div style={{ margin: "12px 0" }}>
        <input
          id="join_code"
          placeholder="Enter room code"
          value={code}
          onChange={(e) => setCode(e.target.value)}
          style={{
            padding: "8px",
            width: "220px",
            marginLeft: "8px",
            borderRadius: "6px",
            border: "1px solid #333",
            background: "#1a1a1b",
            color: "#fff"
          }}
        />
        <button
          onClick={joinRoom}
          style={{
            background: "#1976d2",
            color: "#fff",
            border: "none",
            padding: "10px 14px",
            borderRadius: "6px",
            cursor: "pointer",
            marginLeft: "8px"
          }}
        >
          Join Room
        </button>
      </div>

      <div style={{ color: "#9aa0a6", marginTop: "8px" }}>
        {status}
      </div>
    </div>
  );
}
